CREATE TABLE reviews (id BIGINT AUTO_INCREMENT PRIMARY KEY, product_id BIGINT NOT NULL, user_id BIGINT NOT NULL, rating INT NOT NULL CHECK (rating BETWEEN 1 AND 5), comment CLOB, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT uq_reviews_user_product UNIQUE(user_id, product_id), CONSTRAINT fk_reviews_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE, CONSTRAINT fk_reviews_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX idx_reviews_product ON reviews(product_id); CREATE INDEX idx_reviews_user ON reviews(user_id);
